cat > /workspace/main.go << 'EOF'
package main

import (
	"bufio"
	"encoding/json"
	"flag"
	"fmt"
	"io"
	"os"
	"sort"
	"strings"
	"time"
)

type Module struct {
	Path     string    `json:"Path"`
	Version  string    `json:"Version"`
	Time     time.Time `json:"Time"`
	Indirect bool      `json:"Indirect"`
	Update   *struct {
		Path    string    `json:"Path"`
		Version string    `json:"Version"`
		Time    time.Time `json:"Time"`
	} `json:"Update"`
	GoMod string `json:"GoMod"`
}

func main() {
	var (
		updateOnly bool
		directOnly bool
		ciMode     bool
		style      string
	)

	flag.BoolVar(&updateOnly, "update", false, "List only modules with updates")
	flag.BoolVar(&directOnly, "direct", false, "List only direct modules")
	flag.BoolVar(&ciMode, "ci", false, "Non-zero exit code when at least one outdated dependency was found")
	flag.StringVar(&style, "style", "default", "Output style, pass 'markdown' for a Markdown table")
	flag.Parse()

	modules := readModules(os.Stdin)

	// Filter modules based on flags
	filtered := filterModules(modules, updateOnly, directOnly)

	// Check if we found any outdated dependencies for CI mode
	hasOutdated := false
	for _, mod := range filtered {
		if mod.Update != nil {
			hasOutdated = true
			break
		}
	}

	// Print the table
	printTable(filtered, style)

	// Exit with code 1 if CI mode and outdated found
	if ciMode && hasOutdated {
		os.Exit(1)
	}
}

func readModules(input io.Reader) []Module {
	var modules []Module
	scanner := bufio.NewScanner(input)

	for scanner.Scan() {
		line := scanner.Bytes()
		if len(line) == 0 {
			continue
		}

		var mod Module
		if err := json.Unmarshal(line, &mod); err != nil {
			continue
		}
		modules = append(modules, mod)
	}

	return modules
}

func filterModules(modules []Module, updateOnly, directOnly bool) []Module {
	var filtered []Module

	for _, mod := range modules {
		// Filter by -update flag
		if updateOnly && mod.Update == nil {
			continue
		}

		// Filter by -direct flag
		if directOnly && mod.Indirect {
			continue
		}

		filtered = append(filtered, mod)
	}

	return filtered
}

func isValidTimestamp(mod *Module) bool {
	if mod.Update == nil {
		return true
	}
	return mod.Update.Time.After(mod.Time) || mod.Update.Time.Equal(mod.Time)
}

func printTable(modules []Module, style string) {
	// Sort modules by path for consistent output
	sort.Slice(modules, func(i, j int) bool {
		return modules[i].Path < modules[j].Path
	})

	// Calculate column widths
	columns := []string{"MODULE", "VERSION", "NEW VERSION", "DIRECT", "VALID TIMESTAMPS"}
	widths := make([]int, len(columns))

	for i, col := range columns {
		widths[i] = len(col)
	}

	for _, mod := range modules {
		newVersion := ""
		if mod.Update != nil {
			newVersion = mod.Update.Version
		}

		direct := "true"
		if mod.Indirect {
			direct = "false"
		}

		validTimestamps := "true"
		if !isValidTimestamp(&mod) {
			validTimestamps = "false"
		}

		widths[0] = maxLen(widths[0], len(mod.Path))
		widths[1] = maxLen(widths[1], len(mod.Version))
		widths[2] = maxLen(widths[2], len(newVersion))
		widths[3] = maxLen(widths[3], len(direct))
		widths[4] = maxLen(widths[4], len(validTimestamps))
	}

	if style == "markdown" {
		printMarkdownTable(modules, columns, widths)
	} else {
		printDefaultTable(modules, columns, widths)
	}
}

func printDefaultTable(modules []Module, columns []string, widths []int) {
	// Print top border
	printBorder(widths, "+", "-", "+")

	// Print header
	printRow(columns, widths, "|")

	// Print header border
	printBorder(widths, "+", "-", "+")

	// Print rows
	for _, mod := range modules {
		newVersion := ""
		if mod.Update != nil {
			newVersion = mod.Update.Version
		}

		direct := "true"
		if mod.Indirect {
			direct = "false"
		}

		validTimestamps := "true"
		if !isValidTimestamp(&mod) {
			validTimestamps = "false"
		}

		values := []string{mod.Path, mod.Version, newVersion, direct, validTimestamps}
		printRow(values, widths, "|")
	}

	// Print bottom border
	printBorder(widths, "+", "-", "+")
}

func printMarkdownTable(modules []Module, columns []string, widths []int) {
	// Print header
	printRow(columns, widths, "|")

	// Print separator
	parts := make([]string, len(widths))
	for i, w := range widths {
		parts[i] = strings.Repeat("-", w)
	}
	fmt.Println("|" + strings.Join(parts, "|") + "|")

	// Print rows
	for _, mod := range modules {
		newVersion := ""
		if mod.Update != nil {
			newVersion = mod.Update.Version
		}

		direct := "true"
		if mod.Indirect {
			direct = "false"
		}

		validTimestamps := "true"
		if !isValidTimestamp(&mod) {
			validTimestamps = "false"
		}

		values := []string{mod.Path, mod.Version, newVersion, direct, validTimestamps}
		printRow(values, widths, "|")
	}
}

func printRow(values []string, widths []int, sep string) {
	parts := make([]string, len(values))
	for i, val := range values {
		parts[i] = padString(val, widths[i])
	}
	fmt.Println(sep + strings.Join(parts, sep) + sep)
}

func printBorder(widths []int, corner, line, sep string) {
	parts := make([]string, len(widths))
	for _, w := range widths {
		parts = append(parts, strings.Repeat(line, w))
	}
	fmt.Println(corner + strings.Join(parts, sep) + corner)
}

func padString(s string, width int) string {
	if len(s) >= width {
		return s
	}
	return s + strings.Repeat(" ", width-len(s))
}

func maxLen(a, b int) int {
	if a > b {
		return a
	}
	return b
}
EOF

